-- BIZBOT-STOREFRONT-CONTENT-CONTRACT-001. Synthetic rollback-only tests.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path=extensions,public,pg_catalog;
set local timezone='UTC';
select no_plan();
create function pg_temp.cid(label text) returns uuid language sql immutable as $$select md5('storefront-content-contract-001-'||label)::uuid;$$;
create function pg_temp.version_now() returns integer language sql stable as $$select (public.get_restaurant_storefront_content_v1(pg_temp.cid('org-a'),pg_temp.cid('restaurant-a'))->>'version')::integer;$$;
create function pg_temp.content_document() returns jsonb language sql immutable as $$
 select jsonb_build_object('hero_headline','طَعْم رائع','hero_subline','Saved subline','announcement_text','Original announcement',
  'hero',jsonb_build_object('mode','editorial','item_id',null,'format',jsonb_build_object('text','طَعْم رائع','highlight',jsonb_build_object('start',0,'end',5),'break_before',6),'eyebrow',null,'stamp',null,'footnote',null),
  'announcement_segments',null,'promo',null,'story',null,'category_presentation','[]'::jsonb,'item_presentation','[]'::jsonb);
$$;
create function pg_temp.content_save(label text,document jsonb,ver integer default null,branch text default 'a') returns jsonb language sql volatile as $$
 select public.set_restaurant_storefront_content_v1(pg_temp.cid('request-'||label),pg_temp.cid('org-a'),pg_temp.cid('restaurant-a'),coalesce(ver,pg_temp.version_now()),pg_temp.cid('branch-'||branch),document);
$$;
insert into organizations(id,name,slug,default_currency) values(pg_temp.cid('org-a'),'Content A','content-contract-a','ILS'),(pg_temp.cid('org-b'),'Content B','content-contract-b','ILS');
insert into restaurants(id,organization_id,name,timezone) select pg_temp.cid('restaurant-'||r),pg_temp.cid(case when r='b' then 'org-b' else 'org-a' end),'Content '||r,'UTC' from unnest(array['a','b','missing']) r;
insert into branches(id,organization_id,restaurant_id,name,timezone,tax_enabled,tax_mode) select pg_temp.cid('branch-'||r),pg_temp.cid(case when r='b' then 'org-b' else 'org-a' end),pg_temp.cid(case when r='a2' then 'restaurant-a' else 'restaurant-'||r end),'Content branch '||r,'UTC',false,'exclusive' from unnest(array['a','a2','b','missing']) r;
insert into menu_categories(id,organization_id,restaurant_id,branch_id,name,is_active) select pg_temp.cid('category-'||r),pg_temp.cid(case when r='b' then 'org-b' else 'org-a' end),pg_temp.cid(case when r='b' then 'restaurant-b' else 'restaurant-a' end),case when r='a2' then pg_temp.cid('branch-a2') end,'Category '||r,true from unnest(array['a','a2','b']) r;
insert into menu_items(id,organization_id,restaurant_id,menu_category_id,name,base_price_minor,currency_code,display_order) select pg_temp.cid('item-'||r),pg_temp.cid(case when r='b' then 'org-b' else 'org-a' end),pg_temp.cid('restaurant-'||r),pg_temp.cid('category-'||r),'Stored item '||r,1234,'ILS',1 from unnest(array['a','b']) r;
insert into restaurant_storefront_profiles(restaurant_id,organization_id,storefront_branch_id,slug,display_name,hero_headline,hero_subline,announcement_text,public_phone,is_published,version) select pg_temp.cid('restaurant-'||r),pg_temp.cid('org-'||r),pg_temp.cid('branch-'||r),'content-contract-'||r,'Content '||r,'Old headline','Old subline','Old notice','0521234567',true,10 from unnest(array['a','b']) r;
insert into app_users(id,email) select pg_temp.cid('user-'||r),'content-'||r||'@example.test' from unnest(array['manager','cashier','foreign','branch','missing']) r;
insert into memberships(id,app_user_id,organization_id,restaurant_id,branch_id,role) values
 (pg_temp.cid('membership-manager'),pg_temp.cid('user-manager'),pg_temp.cid('org-a'),pg_temp.cid('restaurant-a'),null,'manager'),
 (pg_temp.cid('membership-cashier'),pg_temp.cid('user-cashier'),pg_temp.cid('org-a'),pg_temp.cid('restaurant-a'),null,'cashier'),
 (pg_temp.cid('membership-foreign'),pg_temp.cid('user-foreign'),pg_temp.cid('org-b'),null,null,'org_owner'),
 (pg_temp.cid('membership-branch'),pg_temp.cid('user-branch'),pg_temp.cid('org-a'),pg_temp.cid('restaurant-a'),pg_temp.cid('branch-a'),'manager'),
 (pg_temp.cid('membership-missing'),pg_temp.cid('user-missing'),pg_temp.cid('org-a'),pg_temp.cid('restaurant-missing'),null,'manager');
create temp table original_content_profile as select to_jsonb(p) v from public.restaurant_storefront_profiles p where restaurant_id=pg_temp.cid('restaurant-a');
select ok(relrowsecurity and relforcerowsecurity,'private sidecar forced RLS: '||relname) from pg_class where oid in ('app.storefront_content_profiles'::regclass,'app.storefront_category_presentation'::regclass,'app.storefront_item_presentation'::regclass);
select is((select count(*) from pg_policy where polrelid=relation::regclass),4::bigint,'four deny policies on '||relation) from unnest(array['app.storefront_content_profiles','app.storefront_category_presentation','app.storefront_item_presentation']) relation;
select ok(not has_table_privilege(role,'app.storefront_content_profiles','SELECT,INSERT,UPDATE,DELETE'),'no direct content data access: '||role) from unnest(array['anon','authenticated','service_role']) role;
select ok(not has_function_privilege(role,'public.set_restaurant_storefront_content_v1(uuid,uuid,uuid,integer,uuid,jsonb)','EXECUTE'),'no content mutation grant: '||role) from unnest(array['anon','service_role']) role;
select is(has_function_privilege(role,'public.storefront_menu_v4(text)','EXECUTE'),has_function_privilege(role,'public.storefront_menu_v3(text)','EXECUTE'),'v4 mirrors v3 grants: '||role) from unnest(array['anon','authenticated','service_role']) role;
select is((select provolatile::text from pg_proc where oid='public.storefront_menu_v4(text)'::regprocedure),'s','v4 stable snapshot');
select is((select count(*) from regexp_matches(pg_get_functiondef('public.storefront_menu_v4(text)'::regprocedure),'public.storefront_menu_v3\(p_slug\)','g')),1::bigint,'v3 exactly once');
select ok(not (select prosecdef from pg_proc where oid='public.set_restaurant_storefront_content_v1(uuid,uuid,uuid,integer,uuid,jsonb)'::regprocedure),'public write is invoker wrapper');
select is((public.storefront_menu_v4('content-contract-a')-'content_v1'-'server_ts'),(public.storefront_menu_v3('content-contract-a')-'server_ts'),'unchanged v3 base envelope');
select is(public.storefront_menu_v4('content-contract-a')#>'{content_v1,hero}',jsonb_build_object('mode','editorial','item_id',null,'format',null,'eyebrow',null,'stamp',null,'footnote',null),'old profile has complete default hero');

set local role anon;
select throws_ok($$select pg_temp.content_save('anon',pg_temp.content_document(),10)$$,'42501',null,'anonymous mutation refused');
reset role;
set local role authenticated;
select set_config('app.current_app_user_id',pg_temp.cid('user-cashier')::text,true);
select is(public.get_restaurant_storefront_content_v1(pg_temp.cid('org-a'),pg_temp.cid('restaurant-a'))->>'error','not_found','rank1 private read does not disclose content');
select is(pg_temp.content_save('cashier',pg_temp.content_document(),10)->>'error','permission_denied','cashier denied');
select throws_ok($$select public.set_restaurant_storefront_content_v1(pg_temp.cid('request-wrong-org'),pg_temp.cid('org-a'),pg_temp.cid('restaurant-b'),10,pg_temp.cid('branch-b'),pg_temp.content_document())$$,'42501',null,'wrong restaurant ancestry denied before cashier audit');
select set_config('app.current_app_user_id',pg_temp.cid('user-foreign')::text,true);
select throws_ok($$select public.get_restaurant_storefront_content_v1(pg_temp.cid('org-a'),pg_temp.cid('restaurant-a'))$$,'42501',null,'rank0 private read refused');
select throws_ok($$select pg_temp.content_save('foreign',pg_temp.content_document(),10)$$,'42501',null,'foreign owner denied');
select set_config('app.current_app_user_id',pg_temp.cid('user-branch')::text,true);
select throws_ok($$select pg_temp.content_save('branch-only',pg_temp.content_document(),10)$$,'42501',null,'branch manager cannot edit restaurant-wide content');
select set_config('app.current_app_user_id',pg_temp.cid('user-missing')::text,true);
select is(public.set_restaurant_storefront_content_v1(pg_temp.cid('request-missing'),pg_temp.cid('org-a'),pg_temp.cid('restaurant-missing'),0,pg_temp.cid('branch-missing'),pg_temp.content_document())->>'error','not_found','authorized missing profile is not created');
select set_config('app.current_app_user_id',pg_temp.cid('user-manager')::text,true);
select is(pg_temp.content_save('branch-conflict',pg_temp.content_document(),10,'a2')->>'error','branch_conflict','new write binds expected branch');
select is(pg_temp.content_save('cas',pg_temp.content_document(),9)->>'error','version_conflict','one global profile version');
select is(pg_temp.content_save('shape-'||n,p,10)->>'error','invalid','strict complete document '||n) from (values(1,'null'::jsonb),(2,'{}'::jsonb),(3,pg_temp.content_document()||'{"unexpected":"never echo this"}'::jsonb),(4,pg_temp.content_document()-'hero')) x(n,p);
select is(pg_temp.content_save('bad-format',jsonb_set(pg_temp.content_document(),'{hero,format,highlight,start}','1'),10)->>'reason','headline_format_invalid','Arabic grapheme cannot be split');
select is(pg_temp.content_save('bad-control',jsonb_set(pg_temp.content_document(),'{hero,eyebrow}',to_jsonb(E'\nCaption'::text)),10)->>'reason','text_invalid','raw invalid control rejected before trim');
select is(pg_temp.content_save('valid',pg_temp.content_document(),10)->>'version','11','valid document saves once');
select is(pg_temp.content_save('valid',pg_temp.content_document(),10)->>'idempotent_replay','true','exact raw replay returns original result');
select throws_ok($$select pg_temp.content_save('valid',jsonb_set(pg_temp.content_document(),'{hero_headline}',to_jsonb(' طَعْم رائع '::text)),10)$$,'42501',null,'normalization-equivalent changed raw identity is not replay');
select is(public.get_restaurant_storefront_content_v1(pg_temp.cid('org-a'),pg_temp.cid('restaurant-a'))#>'{document,hero,format}',pg_temp.content_document()#>'{hero,format}','format survives validated atomic save');
reset role;
select ok(not exists(select 1 from public.restaurant_storefront_profiles where restaurant_id=pg_temp.cid('restaurant-missing')),'missing profile remains absent');
select ok(not exists(select 1 from public.audit_events where restaurant_id=pg_temp.cid('restaurant-b') and actor_app_user_id=pg_temp.cid('user-cashier')),'wrong ancestry created no foreign audit row');
select is((select to_jsonb(p)-'hero_headline'-'hero_subline'-'announcement_text'-'version'-'updated_at' from public.restaurant_storefront_profiles p where restaurant_id=pg_temp.cid('restaurant-a')),(select v-'hero_headline'-'hero_subline'-'announcement_text'-'version'-'updated_at' from original_content_profile),'merchant phone/Featured/theme/operational fields unchanged');
select is(public.storefront_menu_v4('content-contract-a')#>'{content_v1,hero,format}',pg_temp.content_document()#>'{hero,format}','v4 publishes validated format against same headline');

-- Inject a failure AFTER legacy text, sidecar updates and claim. A real raised
-- exception, caught by pgTAP's subtransaction, proves state rollback.
create function pg_temp.fail_content_audit() returns trigger language plpgsql as $$begin if new.action='settings.storefront.content.updated' then raise exception 'synthetic-content-postwrite-failure';end if;return new;end;$$;
create trigger content_test_postwrite_failure before insert on public.audit_events for each row execute function pg_temp.fail_content_audit();
create temp table before_failed_save as select public.get_restaurant_storefront_content_v1(pg_temp.cid('org-a'),pg_temp.cid('restaurant-a')) v;
set local role authenticated;
select throws_ok($$select pg_temp.content_save('injected-failure',jsonb_set(pg_temp.content_document(),'{hero_headline}',to_jsonb('Changed headline'::text))||jsonb_build_object('hero',jsonb_set(pg_temp.content_document()->'hero','{format}','null')))$$,'P0001','synthetic-content-postwrite-failure','failure after underlying mutations raises');
reset role;
drop trigger content_test_postwrite_failure on public.audit_events;
select is(public.get_restaurant_storefront_content_v1(pg_temp.cid('org-a'),pg_temp.cid('restaurant-a')),(select v from before_failed_save),'text/format/sidecar/version all rolled back');
select ok(not exists(select 1 from management_request_results where client_request_id=pg_temp.cid('request-injected-failure')),'failed transaction leaves no idempotency claim');
select ok(not exists(select 1 from audit_events where action='settings.storefront.content.format_invalidated' and restaurant_id=pg_temp.cid('restaurant-a')),'format invalidation audit rolled back too');

set local role authenticated;
select is(public.set_restaurant_storefront_home_content(pg_temp.cid('same-text'),pg_temp.cid('org-a'),pg_temp.cid('restaurant-a'),pg_temp.version_now(),jsonb_build_object('hero_headline','طَعْم رائع','hero_subline','Different subline','announcement_text','Different notice'))->>'ok','true','old writer remains compatible');
select is(public.get_restaurant_storefront_content_v1(pg_temp.cid('org-a'),pg_temp.cid('restaurant-a'))#>'{document,hero,format}',pg_temp.content_document()#>'{hero,format}','same headline old write retains format');
select is(public.set_restaurant_storefront_home_content(pg_temp.cid('changed-text'),pg_temp.cid('org-a'),pg_temp.cid('restaurant-a'),pg_temp.version_now(),jsonb_build_object('hero_headline','New headline','hero_subline','Different subline','announcement_text','Different notice'))->>'ok','true','old changed-headline write succeeds');
select is(public.get_restaurant_storefront_content_v1(pg_temp.cid('org-a'),pg_temp.cid('restaurant-a'))#>'{document,hero,format}','null'::jsonb,'old changed headline atomically invalidates format');
select is(pg_temp.content_save('restore',pg_temp.content_document())->>'ok','true','restore complete valid content');
reset role;
update public.restaurant_storefront_profiles set storefront_branch_id=pg_temp.cid('branch-a2'),version=version+1 where restaurant_id=pg_temp.cid('restaurant-a');
set local role authenticated;
select is(pg_temp.content_save('restore',pg_temp.content_document(),13)->>'idempotent_replay','true','exact replay survives later branch change without reapplying');
reset role;
select is((select storefront_branch_id from restaurant_storefront_profiles where restaurant_id=pg_temp.cid('restaurant-a')),pg_temp.cid('branch-a2'),'replay did not restore old branch');
select ok((select deleted_at is not null from app.storefront_content_profiles where restaurant_id=pg_temp.cid('restaurant-a') and storefront_branch_id=pg_temp.cid('branch-a')),'old branch content tombstoned');
update public.restaurant_storefront_profiles set storefront_branch_id=pg_temp.cid('branch-a'),version=version+1 where restaurant_id=pg_temp.cid('restaurant-a');
set local role authenticated;
select is(public.get_restaurant_storefront_content_v1(pg_temp.cid('org-a'),pg_temp.cid('restaurant-a'))#>'{document,hero,format}','null'::jsonb,'returning to old branch does not resurrect metadata');
reset role;

-- Closed validation categories and cross-restaurant/current-branch relations.
set local role authenticated;
select is(pg_temp.content_save('foreign-item',jsonb_set(pg_temp.content_document(),'{hero}',jsonb_build_object('mode','item','item_id',pg_temp.cid('item-b'),'format',null,'eyebrow',null,'stamp',null,'footnote',null)))->>'field','hero.item_id','foreign item refused without existence details');
select is(pg_temp.content_save('wrong-branch-category',jsonb_set(pg_temp.content_document(),'{category_presentation}',jsonb_build_array(jsonb_build_object('category_id',pg_temp.cid('category-a2'),'heading',null,'blurb',null,'editorial_media_id',null,'image_fit',null,'card_layout','cutout'))))->>'reason','target_invalid','other branch category refused');
select is(pg_temp.content_save('duplicates',jsonb_set(pg_temp.content_document(),'{item_presentation}',jsonb_build_array(jsonb_build_object('item_id',pg_temp.cid('item-a'),'image_fit','fill','card_layout',null),jsonb_build_object('item_id',pg_temp.cid('item-a'),'image_fit','whole-image','card_layout',null))))->>'reason','duplicate_id','duplicate IDs fail as a whole');
select is(pg_temp.content_save('bad-enum',jsonb_set(pg_temp.content_document(),'{item_presentation}',jsonb_build_array(jsonb_build_object('item_id',pg_temp.cid('item-a'),'image_fit','guess-from-name','card_layout',null))))->>'reason','presentation_invalid','unknown presentation enum refused');
select is(pg_temp.content_save('malformed-story',jsonb_set(pg_temp.content_document(),'{story}',jsonb_build_object('kicker','K','title','T','body','B','editorial_media_id',pg_temp.cid('none'),'facts','{}'::jsonb)))->>'reason','presentation_invalid','nonarray facts give fixed error without unhandled JSON call');
select is(pg_temp.content_save('oversize',pg_temp.content_document()||jsonb_build_object('extra',repeat('x',262144)))->>'reason','document_too_large','whole document bounded before field processing');
select is(pg_temp.content_save('trim',jsonb_set(pg_temp.content_document(),'{hero,eyebrow}',to_jsonb(U&'\00A0Saved\2000'::text)))->>'ok','true','specified edge spaces normalize once');
select is(public.get_restaurant_storefront_content_v1(pg_temp.cid('org-a'),pg_temp.cid('restaurant-a'))#>>'{document,hero,eyebrow}','Saved','trimmed new text readback exact');
select is(pg_temp.content_save('empty-segments',jsonb_set(pg_temp.content_document(),'{announcement_segments}','[]'))->>'ok','true','empty segments clear without changing legacy announcement');
select is(public.get_restaurant_storefront_content_v1(pg_temp.cid('org-a'),pg_temp.cid('restaurant-a'))#>'{document,announcement_segments}','null'::jsonb,'empty segments normalized to null');
reset role;

create temp table content_noop_version as select pg_temp.version_now() version;
set local role authenticated;
select is(pg_temp.content_save('new-noop',pg_temp.content_document())->>'ok','true','new complete no-op is still a new management mutation');
reset role;
select is(pg_temp.version_now(),(select version+1 from content_noop_version),'new no-op advances global CAS exactly once');

-- Synthetic public-object metadata reproduces the publisher contract, never
-- downloads or proves image bytes. Originals belong to this exact restaurant.
create function pg_temp.original_key(label text) returns text language sql immutable as $$select pg_temp.cid('org-a')::text||'/'||pg_temp.cid('restaurant-a')::text||'/logo/'||pg_temp.cid('original-'||label)::text||'.png';$$;
insert into storage.objects(bucket_id,name) values('restaurant-logos',pg_temp.original_key('editorial'));
insert into public.storefront_media(id,organization_id,restaurant_id,source_bucket,source_key,variant,object_key,content_hash,width,height,bytes,published_at)
select pg_temp.cid('media-'||label),pg_temp.cid('org-a'),pg_temp.cid('restaurant-a'),'restaurant-logos',pg_temp.original_key('editorial'),'w960',app.storefront_media_prefix(pg_temp.cid('restaurant-a'))||'/'||repeat(ch,64)||'.webp',repeat(ch,64),960,640,1000,case when label='old' then now() end from (values('old','a'),('new','b')) x(label,ch);
insert into storage.objects(bucket_id,name,metadata) select 'storefront-media',object_key,'{"mimetype":"image/webp","size":1000}'::jsonb from public.storefront_media where id in(pg_temp.cid('media-old'),pg_temp.cid('media-new'));
create function pg_temp.media_document() returns jsonb language sql stable as $$select pg_temp.content_document()||jsonb_build_object(
 'hero',jsonb_build_object('mode','item','item_id',pg_temp.cid('item-a'),'format',pg_temp.content_document()#>'{hero,format}','eyebrow','Merchant caption','stamp',null,'footnote',null),
 'announcement_segments',jsonb_build_array('أهلاً',U&'\05E9\05DC\05D5\05DD','Saved English'),
 'promo',jsonb_build_object('target',jsonb_build_object('kind','category','category_id',pg_temp.cid('category-a')),'kicker','Promo','title','Saved title','body','Saved body','editorial_media_id',pg_temp.cid('media-old')),
 'story',jsonb_build_object('kicker','Story','title','Saved story','body','Saved paragraph','editorial_media_id',pg_temp.cid('media-old'),'facts',jsonb_build_array('Merchant claim')),
 'category_presentation',jsonb_build_array(jsonb_build_object('category_id',pg_temp.cid('category-a'),'heading','Saved section','blurb',null,'editorial_media_id',pg_temp.cid('media-old'),'image_fit','whole-image','card_layout','cutout')),
 'item_presentation',jsonb_build_array(jsonb_build_object('item_id',pg_temp.cid('item-a'),'image_fit','fill','card_layout','standard')));$$;
set local role authenticated;
select is(pg_temp.content_save('media-content',pg_temp.media_document())->>'ok','true','publish-only editorial refs, category and item settings save');
select is((public.retract_storefront_media(pg_temp.cid('retract-in-use'),pg_temp.cid('org-a'),pg_temp.cid('restaurant-a'),pg_temp.cid('media-old')))->>'error','media_in_use','old retract refuses content-only live references');
select is((public.retract_storefront_media(pg_temp.cid('retract-in-use-2'),pg_temp.cid('org-a'),pg_temp.cid('restaurant-a'),pg_temp.cid('media-old')))->'slots','[]'::jsonb,'old retract does not invent Hero usage enum');
select is((public.list_storefront_media(pg_temp.cid('org-a'),pg_temp.cid('restaurant-a'))->'media')->0->'in_use','[]'::jsonb,'old list preserves old in_use enum contract');
select is((select jsonb_array_length(m->'content_in_use') from jsonb_array_elements(public.list_storefront_content_media_v1(pg_temp.cid('org-a'),pg_temp.cid('restaurant-a'))->'media') x(m) where m->>'id'=pg_temp.cid('media-old')::text),3,'new media list describes all three active usages');
reset role;
select is((select hero_media_id from public.restaurant_storefront_profiles where restaurant_id=pg_temp.cid('restaurant-a')),null::uuid,'content-media selection never assigns Hero slot');
create temp table before_media_replacement as select version from public.restaurant_storefront_profiles where restaurant_id=pg_temp.cid('restaurant-a');
create function pg_temp.fail_media_repoint_audit() returns trigger language plpgsql as $$begin if new.action='settings.storefront.content.media_replaced' then raise exception 'synthetic-media-repoint-failure';end if;return new;end;$$;
create trigger content_test_media_failure before insert on public.audit_events for each row execute function pg_temp.fail_media_repoint_audit();
set local role authenticated;
select throws_ok($$select public.finalize_storefront_media(pg_temp.cid('finalize-failure'),pg_temp.cid('org-a'),pg_temp.cid('restaurant-a'),pg_temp.cid('media-new'))$$,'P0001','synthetic-media-repoint-failure','failure after media/refs changes raises');
reset role;
drop trigger content_test_media_failure on public.audit_events;
select ok((select published_at is not null and unpublished_at is null from public.storefront_media where id=pg_temp.cid('media-old')),'failed replacement kept old object live');
select is((select published_at from public.storefront_media where id=pg_temp.cid('media-new')),null::timestamptz,'failed replacement left new object staged');
select ok((select promo_media_id=pg_temp.cid('media-old') and story_media_id=pg_temp.cid('media-old') from app.storefront_content_profiles where restaurant_id=pg_temp.cid('restaurant-a') and storefront_branch_id=pg_temp.cid('branch-a')),'failed replacement rolled every content ref back');
select is(pg_temp.version_now(),(select version from before_media_replacement),'failed replacement preserved shared version');
select ok(not exists(select 1 from management_request_results where client_request_id=pg_temp.cid('finalize-failure')),'failed replacement rolled ledger back');
set local role authenticated;
select is(public.finalize_storefront_media(pg_temp.cid('finalize-new'),pg_temp.cid('org-a'),pg_temp.cid('restaurant-a'),pg_temp.cid('media-new'))->>'ok','true','same-source replacement succeeds');
select is(public.finalize_storefront_media(pg_temp.cid('finalize-new'),pg_temp.cid('org-a'),pg_temp.cid('restaurant-a'),pg_temp.cid('media-new'))->>'idempotent_replay','true','replacement replay returns stored result');
reset role;
select is(pg_temp.version_now(),(select version+1 from before_media_replacement),'replacement advances one global version exactly once');
select ok((select promo_media_id=pg_temp.cid('media-new') and story_media_id=pg_temp.cid('media-new') from app.storefront_content_profiles where restaurant_id=pg_temp.cid('restaurant-a') and storefront_branch_id=pg_temp.cid('branch-a')),'Promo and Story repointed atomically');
select is((select editorial_media_id from app.storefront_category_presentation where restaurant_id=pg_temp.cid('restaurant-a') and storefront_branch_id=pg_temp.cid('branch-a') and category_id=pg_temp.cid('category-a')),pg_temp.cid('media-new'),'category repointed in same replacement');
select ok((select unpublished_at is not null from public.storefront_media where id=pg_temp.cid('media-old')),'replaced object registration retracted');
select is(public.storefront_menu_v4('content-contract-a')#>>'{content_v1,promo,image_url}','/storage/v1/object/public/storefront-media/'||app.storefront_media_prefix(pg_temp.cid('restaurant-a'))||'/'||repeat('b',64)||'.webp','public projection exposes relative derivative path only');
select ok(not (public.storefront_menu_v4('content-contract-a')->'content_v1')::text like '%'||pg_temp.cid('media-new')::text||'%','private media identity never serialized');

-- Retraction outside the supported manager path is projected safely. A missing
-- canonical item image remains missing; presentation never invents an image.
update public.storefront_media set unpublished_at=now() where id=pg_temp.cid('media-new');
select is(public.storefront_menu_v4('content-contract-a')#>'{content_v1,promo}','null'::jsonb,'revoked media suppresses category Promo');
select is(public.storefront_menu_v4('content-contract-a')#>'{content_v1,story}','null'::jsonb,'revoked media suppresses complete Story');
select is(public.storefront_menu_v4('content-contract-a')#>'{content_v1,category_presentation,0,image_url}','null'::jsonb,'revoked category image normalizes to null');
insert into public.menu_item_branch_availability(organization_id,restaurant_id,branch_id,menu_item_id,availability,reason) values(pg_temp.cid('org-a'),pg_temp.cid('restaurant-a'),pg_temp.cid('branch-a'),pg_temp.cid('item-a'),'unavailable','sold_out');
select is(public.storefront_menu_v4('content-contract-a')#>>'{content_v1,hero,item_id}',pg_temp.cid('item-a')::text,'sold-out Hero remains canonical valid relation');
select is(public.storefront_menu_v4('content-contract-a')#>>'{content_v1,hero,mode}','item','sold-out Hero remains disabled item mode, not a fabricated replacement');
update public.menu_items set is_active=false where id=pg_temp.cid('item-a');
select is(public.storefront_menu_v4('content-contract-a')#>'{content_v1,hero,item_id}','null'::jsonb,'unpublished Hero target normalizes whole presentation to editorial');
select is(public.storefront_menu_v4('content-contract-a')#>>'{content_v1,hero,mode}','editorial','unpublished Hero never retains product-specific mode');
select is(public.storefront_menu_v4('content-contract-a')#>'{content_v1,item_presentation}','[]'::jsonb,'unpublished item settings omitted');
select ok((public.get_restaurant_storefront_content_v1(pg_temp.cid('org-a'),pg_temp.cid('restaurant-a'))->'warnings') @> '[{"field":"hero.item_id","reason":"relation_unavailable"}]'::jsonb,'manager read emits fixed relation warning');
select ok(not (public.get_restaurant_storefront_content_v1(pg_temp.cid('org-a'),pg_temp.cid('restaurant-a'))->'warnings')::text like '%'||pg_temp.cid('item-a')::text||'%','warnings contain no IDs');
select is(public.storefront_menu_v4('content-contract-b')->'content_v1',jsonb_build_object('schema',1,'hero',jsonb_build_object('mode','editorial','item_id',null,'format',null,'eyebrow',null,'stamp',null,'footnote',null),'announcement_segments',null,'promo',null,'story',null,'category_presentation','[]'::jsonb,'item_presentation','[]'::jsonb),'second restaurant remains independent with complete defaults');

-- UTF-8 scalar, grapheme and token boundaries; no host ICU or normalization.
select is(app.storefront_content_grapheme_boundaries_v1(''),array[0]::integer[],'empty grapheme input');
select is(app.storefront_content_grapheme_boundaries_v1('😀'),array[0,1]::integer[],'non-BMP uses one Unicode scalar');
select ok(app.storefront_content_hero_format_valid_v1('😀 special',0,1,2),'non-BMP token endpoints use scalar offsets');
select ok(not app.storefront_content_hero_format_valid_v1('طَعْم رائع',1,5,6),'Arabic mark endpoint cannot split grapheme');
select ok(app.storefront_content_hero_format_valid_v1(U&'\05E9\05B8\05DC\05D5\05B9\05DD \05D8\05D5\05D1',0,6,7),'Hebrew marks retain scalar boundaries');
select is(app.storefront_content_document_shape_v1(jsonb_set(pg_temp.content_document(),'{hero,format,break_before}','4.5'))->>'error','headline_format_invalid','fractional offset is refused before integer conversion');
select ok(app.storefront_content_text_v1(U&'Old\0085text',120,true),'interior legacy NEL remains compatible');
select ok(not app.storefront_content_hero_format_valid_v1(U&'Old\0085text',0,3,null),'format rejects legacy line separators');
select ok(not app.storefront_content_input_text_v1(to_jsonb(U&'\0085new'::text),60,false),'new raw control rejected before edge trim');
